mapper.select:
SELECT

FROM chat_conversation
WHERE id = #{id}
  AND user_id = #{userId}

SELECT

FROM chat_conversation
WHERE id = #{id}
  AND user_id = #{userId}
FOR UPDATE

SELECT

FROM chat_conversation
WHERE user_id = #{userId}
ORDER BY last_message_at DESC, id DESC
LIMIT #{limit}

SELECT

FROM chat_conversation
WHERE user_id = #{userId}

  AND (
      last_message_at < #{cursorLastMessageAt, jdbcType=TIMESTAMP}
      OR (
          last_message_at = #{cursorLastMessageAt, jdbcType=TIMESTAMP}
          AND id < #{cursorId}
      )
  )

ORDER BY last_message_at DESC, id DESC
LIMIT #{limit}

SELECT

FROM chat_conversation
WHERE user_id = #{userId}
  AND project_id = #{projectId}
ORDER BY last_message_at DESC, id DESC
LIMIT #{limit}

SELECT

FROM chat_conversation
WHERE user_id = #{userId}
  AND project_id IS NULL
ORDER BY last_message_at DESC, id DESC
LIMIT #{limit}

mapper.update:
UPDATE chat_conversation
SET title = #{title}
WHERE id = #{id}
  AND user_id = #{userId}

UPDATE chat_conversation
SET project_id = #{projectId, jdbcType=CHAR}
WHERE id = #{id}
  AND user_id = #{userId}

  AND EXISTS (
      SELECT 1
      FROM chat_project
      WHERE chat_project.id = #{projectId}
        AND chat_project.user_id = #{userId}
  )

UPDATE chat_conversation
SET last_message_at = #{lastMessageAt}
WHERE id = #{id}
  AND user_id = #{userId}

mapper.delete:
DELETE FROM chat_conversation
WHERE id = #{id}
  AND user_id = #{userId}
